using System.Text.RegularExpressions;
using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    // ── FormatPhoneNumber ───────────────────────────────────────

    [TestMethod]
    public void FormatPhoneNumber_ReturnsCorrectFormat()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");

        Assert.AreEqual("(212) 555-1234", result);
    }

    [TestMethod]
    public void FormatPhoneNumber_StartsWithAreaCodeInParens()
    {
        var result = _formatter.FormatPhoneNumber("8005559999");

        StringAssert.StartsWith(result, "(800)");
    }

    [TestMethod]
    public void FormatPhoneNumber_EndsWithLastFourDigits()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");

        StringAssert.EndsWith(result, "-1234");
    }

    [TestMethod]
    public void FormatPhoneNumber_ContainsExchangeCode()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");

        StringAssert.Contains(result, "555");
    }

    [TestMethod]
    public void FormatPhoneNumber_MatchesPattern()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");

        StringAssert.Matches(result, new Regex(@"^\(\d{3}\) \d{3}-\d{4}$"));
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _formatter.FormatPhoneNumber(null!));
    }

    [TestMethod]
    [DataRow("123")]
    [DataRow("12345678901")]
    [DataRow("")]
    public void FormatPhoneNumber_WrongLength_Throws(string digits)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.FormatPhoneNumber(digits));
    }

    // ── BuildGreeting ───────────────────────────────────────────

    [TestMethod]
    public void BuildGreeting_DefaultTitle_ReturnsCorrectGreeting()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.AreEqual("Dear Mr. Smith,", result);
    }

    [TestMethod]
    public void BuildGreeting_StartsWithDear()
    {
        var result = _formatter.BuildGreeting("Jones", "Dr.");

        StringAssert.StartsWith(result, "Dear ");
    }

    [TestMethod]
    public void BuildGreeting_EndsWithComma()
    {
        var result = _formatter.BuildGreeting("Jones", "Dr.");

        StringAssert.EndsWith(result, ",");
    }

    [TestMethod]
    public void BuildGreeting_ContainsTitle()
    {
        var result = _formatter.BuildGreeting("Jones", "Dr.");

        StringAssert.Contains(result, "Dr.");
    }

    [TestMethod]
    public void BuildGreeting_CustomTitle()
    {
        var result = _formatter.BuildGreeting("Adams", "Ms.");

        Assert.AreEqual("Dear Ms. Adams,", result);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void BuildGreeting_InvalidName_Throws(string? name)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.BuildGreeting(name!));
    }

    // ── GenerateSlug ────────────────────────────────────────────

    [TestMethod]
    public void GenerateSlug_SimpleTitle()
    {
        var result = _formatter.GenerateSlug("Hello World");

        Assert.AreEqual("hello-world", result);
    }

    [TestMethod]
    public void GenerateSlug_StartsWithFirstWord()
    {
        var result = _formatter.GenerateSlug("My Great Article!");

        StringAssert.StartsWith(result, "my");
    }

    [TestMethod]
    public void GenerateSlug_EndsWithLastWord()
    {
        var result = _formatter.GenerateSlug("My Great Article!");

        StringAssert.EndsWith(result, "article");
    }

    [TestMethod]
    public void GenerateSlug_DoesNotMatchUppercase()
    {
        var result = _formatter.GenerateSlug("Hello World");

        StringAssert.DoesNotMatch(result, new Regex("[A-Z]"));
    }

    [TestMethod]
    public void GenerateSlug_MatchesSlugPattern()
    {
        var result = _formatter.GenerateSlug("  Some!! Complex** Title  ");

        StringAssert.Matches(result, new Regex(@"^[a-z0-9]+(-[a-z0-9]+)*$"));
    }

    [TestMethod]
    public void GenerateSlug_CollapsesSpecialChars()
    {
        var result = _formatter.GenerateSlug("a---b***c");

        Assert.AreEqual("a-b-c", result);
    }

    [TestMethod]
    public void GenerateSlug_TrimsLeadingAndTrailingHyphens()
    {
        var result = _formatter.GenerateSlug("!!hello!!");

        Assert.AreEqual("hello", result);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GenerateSlug_InvalidTitle_Throws(string? title)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.GenerateSlug(title!));
    }

    // ── FormatCurrency ──────────────────────────────────────────

    [TestMethod]
    public void FormatCurrency_DefaultSymbol()
    {
        var result = _formatter.FormatCurrency(19.99m);

        Assert.AreEqual("$19.99", result);
    }

    [TestMethod]
    public void FormatCurrency_StartsWithSymbol()
    {
        var result = _formatter.FormatCurrency(5m, "€");

        StringAssert.StartsWith(result, "€");
    }

    [TestMethod]
    public void FormatCurrency_EndsWithTwoDecimalPlaces()
    {
        var result = _formatter.FormatCurrency(10m);

        StringAssert.EndsWith(result, ".00");
    }

    [TestMethod]
    public void FormatCurrency_MatchesDecimalFormat()
    {
        var result = _formatter.FormatCurrency(1234.5m, "£");

        StringAssert.Matches(result, new Regex(@"^£\d+\.\d{2}$"));
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount()
    {
        var result = _formatter.FormatCurrency(-42.10m);

        StringAssert.StartsWith(result, "$-");
        StringAssert.EndsWith(result, ".10");
    }

    [TestMethod]
    public void FormatCurrency_Zero()
    {
        var result = _formatter.FormatCurrency(0m);

        Assert.AreEqual("$0.00", result);
    }
}

